@classmethod
def combinable_nodes(
    cls, nodes: list[BaseSchedulerNode]
) -> list[BaseSchedulerNode]:
    extern = [x for x in nodes if isinstance(x, ExternKernelSchedulerNode)]
    if extern:
        log.debug(
            "ComboKernels: %d external nodes are filtered %s",
            len(extern),
            [node.node.get_origins() for node in extern if node.node is not None],
        )
    grouped = [x for x in nodes if isinstance(x, GroupedSchedulerNode)]
    if grouped:
        log.debug(
            "ComboKernels: %d grouped nodes are filtered",
            len(grouped),
        )
    mix_order = [x for x in nodes if isinstance(x, FusedMixOrderReductions)]
    if mix_order:
        log.debug(
            "ComboKernels: %d FusedMixOrderReductions nodes are filtered",
            len(mix_order),
        )
    nested_reductions = [x for x in nodes if isinstance(x, FusedNestedReductions)]
    if nested_reductions:
        log.debug(
            "ComboKernels: %d FusedNestedReductions nodes are filtered",
            len(nested_reductions),
        )

    filtered_nodes = [
        x
        for x in nodes
        if not isinstance(
            x,
            (
                NopKernelSchedulerNode,
                ExternKernelSchedulerNode,
                GroupedSchedulerNode,
                FusedMixOrderReductions,
                FusedNestedReductions,
            ),
        )
    ]
    foreach_nodes = [
        x for x in filtered_nodes if isinstance(x, ForeachKernelSchedulerNode)
    ]
    if foreach_nodes:
        log.debug("ComboKernels: %d foreach nodes are filtered", len(foreach_nodes))
    filtered_nodes = [
        x for x in filtered_nodes if not isinstance(x, ForeachKernelSchedulerNode)
    ]
    template_nodes = [x for x in filtered_nodes if x.is_template()]
    if template_nodes:
        log.debug(
            "ComboKernels: %d template nodes are filtered: %s",
            len(template_nodes),
            template_nodes,
        )
    filtered_nodes = [x for x in filtered_nodes if x not in template_nodes]

    # Filter out reduction nodes if combo_kernels_pointwise_only is enabled
    if config.combo_kernels_pointwise_only:
        reduction_nodes = [x for x in filtered_nodes if x.is_reduction()]
        if reduction_nodes:
            log.debug(
                "ComboKernels: %d reduction nodes are filtered (pointwise_only mode)",
                len(reduction_nodes),
            )
        filtered_nodes = [x for x in filtered_nodes if not x.is_reduction()]

    return filtered_nodes

@staticmethod
def _default_group_nodes_for_combo_kernels(
    scheduler: Scheduler,
) -> list[list[BaseSchedulerNode]]:
    """
    Returns a list of lists of nodes that are to be grouped together.
    """
    sorted_nodes = scheduler._topological_sort_nodes()

for num, node_list in enumerate(
    ForeachKernelSchedulerNode.group_nodes_for_combo_kernels(self)
):
    if num_ck_nodes is not None and count > num_ck_nodes:
        break
    members = ForeachKernelSchedulerNode.combinable_nodes(node_list)
    if len(members) < 2:
        continue

    for window in Scheduler._distance_windows(
        members, node_to_idx, max_distance
    ):
        if num_ck_nodes is not None and count > num_ck_nodes:
            break
        if len(window) < 2 or not self.speedup_by_combo_kernel(window):
            continue
        if memory_check:
            assert mem_ctx is not None
            sim_start = time.perf_counter()
            self._try_combo_with_halving(
                window,
                num,
                mem_ctx,
                enable_autotune=enable_autotune,
                on_accept=_register_accept,
            )
            memory_sim_time += time.perf_counter() - sim_start
        else:
            combo_node = ForeachKernelSchedulerNode(
                window[0].scheduler,
                window,
                use_custom_partition_algo=True,
                enable_autotune=enable_autotune,
                per_subkernel_blocks=config.combo_kernel_per_subkernel_blocks,
            )
            _register_accept(combo_node, window, num)

self.nodes = sorted(fused_nodes, key=lambda x: x.min_order)
self.nodes = self.topological_sort_schedule(self.nodes)
log.info(
    "Generated ComboKernel nodes: %d ComboKernels, totally %d -> %d nodes",
    count,

    for item in self.subkernels:
        tile_numel = 1
        for axis in item["tiling_axis"]:
            name = self.axis_name[axis]
            if axis in item["no_loop_axis"] or (
                name.startswith("r") and item["persistent_reduction"]
            ):
                extent = item["size_hints"][name]
                if self.npu_kernel_type == NPUKernelType.SIMT_ONLY:
                    extent = 1 << (extent - 1).bit_length()
            else:
                extent = cfg.get(f"{name.upper()}BLOCK_SUB", 1)
            tile_numel *= extent
        branch_bytes = get_byte_per_numel(item["split_axis_dtype"])
        normalized_numel = (
            tile_numel * branch_bytes + self.dtype_bytes - 1
        ) // self.dtype_bytes
        largest_tile = max(largest_tile, normalized_numel)
    return largest_tile

def descend_split_axis_inner(self, axis_index):
    reached_stop = super().descend_split_axis_inner(axis_index)
    # A combo may be classified as non-tiny even when each branch is tiny.
    # In that case the inherited descent retains several split choices but
    # starts tiling from the final, smaller subblock. Also consider the full
    # block of each retained split choice before descending shared subtiles.
    saved_sub_blocks = self.sub_blocks.copy()
    for candidate in self.candidate_blocks:
        for axis in self.split_axis:
            self.sub_blocks[axis] = candidate[axis]
        self.add_to_configs(candidate)
    self.sub_blocks = saved_sub_blocks

    return self.configs

def add_to_configs(self, candi_block):
    if self.calculate_total_programs(candi_block) > self.max_programs:
        return False
    return super().add_to_configs(candi_block)

def add_to_configs(self, candi_block):
    newcfg = {}
    self.fill_config(newcfg, candi_block)
    total_numel = self.calculate_config_numel(newcfg)
    stop_numel_threshold = 0 if len(self.configs) < 10 or self.tiny_kernel else self.stop_numel + 100
    if not self.valid_tile_numel(total_numel):
        return False
    if self.find_config(newcfg):
        return False
    if total_numel < stop_numel_threshold:
        return False

    # This is tmp check for simt overflow, and will be removed latter
    if self.npu_kernel_type == NPUKernelType.SIMT_ONLY and total_numel * self.dtype_bytes > 8 * 1024:
        return False
    self.configs.append(Config(newcfg, num_warps=1, num_stages=2))
    return True

